struct order_facade {
    const struct order_repo *repo;
    const struct pricing *pricing;   /* structs of function pointers */
};

int order_facade_place(struct order_facade *f, const struct place_order_req *req,
                       struct place_order_resp *out) {
    struct quote q;
    if (f->pricing->quote(f->pricing, req->sku, req->qty, &q) != 0) return -1;
    if (f->repo->reserve(f->repo, req->sku, req->qty) != 0) return -1;
    return f->repo->insert_order(f->repo, &q, out);   /* one DAO-level transaction */
}
